insert into public.authors (id, name, slug, headline, bio) values ('11111111-1111-1111-1111-111111111111', 'Valeria Montes', 'valeria-montes', 'Editora estratégica y consultora de lanzamientos', 'Ayuda a autores y marcas personales a construir productos editoriales rentables.'), ('22222222-2222-2222-2222-222222222222', 'Adrián Vega', 'adrian-vega', 'Estratega de marca y storytelling', 'Combina diseño, posicionamiento y ventas para autores independientes.'), ('33333333-3333-3333-3333-333333333333', 'Noelia Rojas', 'noelia-rojas', 'Growth marketer para infoproductos y publicaciones', 'Diseña sistemas de venta directa y programas de afiliados para marcas de contenido.'), ('44444444-4444-4444-4444-444444444444', 'Samuel Báez', 'samuel-baez', 'Product designer enfocado en plataformas de contenidos', 'Ayuda a negocios editoriales a elevar su experiencia digital.') on conflict (id) do nothing;
insert into public.books (id,author_id,slug,title,subtitle,short_description,description,excerpt,price,compare_at_price,rating,review_count,page_count,language,isbn,formats,categories,badge,is_featured,status,publication_date) values ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaa1','11111111-1111-1111-1111-111111111111','escribe-vende-escala','Escribe, Vende, Escala','Sistema moderno para autores que quieren negocio, no solo aplausos','Manual táctico para publicar, vender y crecer una marca editorial desde Latinoamérica.','Una guía práctica para autores que quieren convertir su libro en un activo comercial. Incluye posicionamiento, validación, funnel, afiliados y estructura de lanzamiento.','Tu libro no es solo contenido: es producto, autoridad y canal de adquisición.',24.90,39.90,4.90,128,244,'Español','978-99999-000-01','{print,ebook,reader,kindle}','{Negocios,Marketing,Autores}','Top seller',true,'published','2026-01-18'), ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaa2','22222222-2222-2222-2222-222222222222','marca-de-autor-360','Marca de Autor 360','Cómo verte premium aunque estés empezando','Branding, oferta, narrativa y presencia para autores con hambre de posicionamiento.','Un framework claro para convertir un manuscrito en una marca editorial atractiva. Incluye identidad, página de autor, ventas directas y contenido para redes.','La portada atrae. La promesa vende. El sistema retiene.',19.90,29.90,4.80,92,196,'Español','978-99999-000-02','{print,ebook,reader}','{Branding,Marketing,Creatividad}','Nuevo',true,'published','2026-02-02'), ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaa3','33333333-3333-3333-3333-333333333333','funnels-para-libros','Funnels para Libros','De lector curioso a cliente recurrente','Embudo, checkout, automatizaciones y ofertas que convierten sin sonar desesperado.','Ideal para autores, editoriales pequeñas y vendedores afiliados. Incluye secuencias, lead magnets, bundles y activación de referidos.','No necesitas más tráfico. Necesitas mejor diseño comercial.',29.90,44.90,4.70,74,318,'Español','978-99999-000-03','{print,ebook,reader,kindle}','{Ventas,Automatización,Negocios}','Afiliable',false,'published','2025-11-14'), ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaa4','44444444-4444-4444-4444-444444444444','biblioteca-digital-premium','Biblioteca Digital Premium','Experiencia de lectura que engancha y retiene','Crea una experiencia digital memorable para tus lectores y miembros.','Aborda UX de lectura, suscripciones, bibliotecas privadas, notas, progreso y activación de comunidad para plataformas editoriales.','Leer en pantalla no tiene que sentirse barato.',17.90,27.00,4.60,51,162,'Español','978-99999-000-04','{ebook,reader}','{UX,Producto digital,Lectura}','Digital',false,'published','2025-10-10') on conflict (id) do nothing;
